  [1220220] = { "Judgementを使うと、$D1の間、与えるHolyダメージが$N1%増加します。最大$N3回まで重なります。", nil, 0xd6c76fb9, nil, "um" },
  [1220222] = { "Crusader Strikeのダメージを$N1%増加させます。", nil, 0x724e48f3, nil, "um" },
